import{_ as r,o as a,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"تمام نسلوں کی نسبتی جائزہ","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0050-万族谱系总览.md","filePath":"ur/0050-万族谱系总览.md"}'),o={name:"ur/0050-万族谱系总览.md"};function n(e,t,d,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="تمام-نسلوں-کی-نسبتی-جائزہ" tabindex="-1">تمام نسلوں کی نسبتی جائزہ <a class="header-anchor" href="#تمام-نسلوں-کی-نسبتی-جائزہ" aria-label="Permalink to &quot;تمام نسلوں کی نسبتی جائزہ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>50</td></tr><tr><td>ماڈیول</td><td>نسلیں اور زندگی کی شکلیں</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>تمام نسلیں، نسبتی درجہ بندی، علامتی تعلق، نسلی برابری، زندگی کا تنوع</td></tr></tbody></table><h2 id="i-تمام-نسلوں-کے-تصور-کی-تعریف" tabindex="-1">I. تمام نسلوں کے تصور کی تعریف <a class="header-anchor" href="#i-تمام-نسلوں-کے-تصور-کی-تعریف" aria-label="Permalink to &quot;I. تمام نسلوں کے تصور کی تعریف&quot;">​</a></h2><p>ہنگ یوآن ژو (مہان آتم اینکر اصلی کائنات) میں، &quot;تمام نسلیں&quot; قطعی طور پر دس ہزار نسلوں کی طرف اشارہ نہیں کرتی، بلکہ کائنات میں تمام وہ زندگی کی شکلیں جن میں ادراک کی صلاحیت اور ارتقائی صلاحیت موجود ہے، کا اجتماعی نام ہے۔ تمام نسلوں کے تصور کا بنیادی نقطہ زندگی کی شکلوں کی لامحدود تنوع کو تسلیم کرنا اور ہر زندگی کی شکل کی علامتی ارتقاء کے نظام میں انوکھی قدر کو تسلیم کرنا ہے۔</p><p>اینکر سمبیوسس تہذیب نے &quot;تمام نسلوں کی برابری&quot; کا بنیادی اصول قائم کیا ہے: تمام زندگی کی شکلیں، چاہے ان کی نسلی ابتدا، جسمانی ساخت، سدھن کی سطح، یا تہذیب کی سطح کچھ بھی ہو، قانون کے سامنے برابر ہیں اور سمبیوسس آئین کے ذریعے دیے گئے بنیادی حقوق سے لطف اندوز ہیں۔ یہ اصول لوٹ مار کے کائناتی نقطہ نظر میں &quot;طاقتور سب کچھ کھا جاتا ہے، کمزور ختم ہو جاتا ہے&quot; کی منطق کی بنیادی تردید ہے۔</p><h2 id="ii-تمام-نسلوں-کی-نسبتی-درجہ-بندی-کا-نظام" tabindex="-1">II. تمام نسلوں کی نسبتی درجہ بندی کا نظام <a class="header-anchor" href="#ii-تمام-نسلوں-کی-نسبتی-درجہ-بندی-کا-نظام" aria-label="Permalink to &quot;II. تمام نسلوں کی نسبتی درجہ بندی کا نظام&quot;">​</a></h2><p>ہنگ یوآن ژو کی نسلیں ان کی زندگی کی شکلوں کی بنیادی خصوصیات کے مطابق پانچ بڑی نسبتی خطوں میں تقسیم ہیں، اور ہر نسبتی خطے کو مخصوص نسلوں میں مزید تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>نسبتی خطہ</th><th>نام</th><th>بنیادی خصوصیت</th><th>نمائندہ نسلیں</th></tr></thead><tbody><tr><td>پہلا نسبتی خطہ</td><td>کاربن پر مبنی مادّی نسل</td><td>وہ زندگی جو کاربن عنصر کو زندگی کی بنیاد کے طور پر اور مادّی جسم کو وجود کی بنیادی شکل کے طور پر لیتی ہے</td><td>انسانی نسل، جانوروں کی نسل، ترچھی نسل، پروں والی نسل، درختوں کی نسل</td></tr><tr><td>دوسرا نسبتی خطہ</td><td>توانائی گاڑھی نسل</td><td>وہ زندگی جو توانائی کے گاڑھاو کو وجود کی بنیادی شکل کے طور پر لیتی ہے، جس میں مادّی جسم معاون یا غیر موجود ہو</td><td>روحانی نسل، آگ کی نسل، پانی کی نسل، ہوا کی نسل، بجلی کی نسل</td></tr><tr><td>تیسرا نسبتی خطہ</td><td>مکینیکل تعمیراتی نسل</td><td>وہ زندگی جو مکینیکل تعمیر کو جسم کے طور پر اور شعور کے مرکز کو زندگی کی بنیاد کے طور پر لیتی ہے</td><td>مشینوں کی نسل، میکانکی نسل، عددی نسل، کرسٹل کی نسل</td></tr><tr><td>چوتھا نسبتی خطہ</td><td>شعوری معلوماتی نسل</td><td>وہ زندگی جو شعور اور معلومات کو وجود کی بنیادی شکل کے طور پر لیتی ہے، مادّی وہک سے الگ ہو سکتی ہے</td><td>خوابوں کی نسل، سائے کی نسل، سوچ کی نسل، روح کی نسل</td></tr><tr><td>پانچواں نسبتی خطہ</td><td>مخلوط تبدیلی نسل</td><td>دو یا زیادہ نسبتی خطوں کی زندگیوں کے انضمام اور تبدیلی سے پیدا ہونے والی نئی زندگی کی شکلیں</td><td>نیم جانور نسل، دیوتا روح نسل، انسان-مشین نسل، دوہری روح جسم</td></tr></tbody></table><p>پانچ نسبتی خطوں کی تقسیم مطلق انزوا نہیں ہے۔ سمبیوسس ارتقاء کی ترقی کے ساتھ ساتھ، نسبتی خطوں کے درمیان انضمام اور تبدیلی کے واقعات بڑھ رہے ہیں، اور پانچواں نسبتی خطہ &quot;مخلوط تبدیلی نسل&quot; کا پیمانہ مسلسل پھیل رہا ہے۔</p><h2 id="iii-اہم-نسلوں-کا-تعارف" tabindex="-1">III. اہم نسلوں کا تعارف <a class="header-anchor" href="#iii-اہم-نسلوں-کا-تعارف" aria-label="Permalink to &quot;III. اہم نسلوں کا تعارف&quot;">​</a></h2><h3 id="الف-کاربن-پر-مبنی-مادّی-نسل" tabindex="-1">(الف) کاربن پر مبنی مادّی نسل <a class="header-anchor" href="#الف-کاربن-پر-مبنی-مادّی-نسل" aria-label="Permalink to &quot;(الف) کاربن پر مبنی مادّی نسل&quot;">​</a></h3><ul><li><strong>انسانی نسل</strong>: ہنگ یوآن ژو میں سب سے زیادہ پھیلی ہوئی اور سب سے زیادہ موافقت پذیر نسلوں میں سے ایک، جو اپنی مضبوط سیکھنے کی صلاحیت، سماجی تعاون کی صلاحیت اور ارتقائی صلاحیت کے لیے مشہور ہے۔ انسانی نسل اینکر سمبیوسس تہذیب کی بنیاد رکھنے والی نسلوں میں سے ایک ہے اور تہذیب کی انتظامیہ میں اہم کردار ادا کرتی ہے۔</li><li><strong>جانوروں کی نسل</strong>: جانوروں کی شکل کی خصوصیات والی نسلیں، جن کی جسمانی صلاحیت اور حواس عام طور پر انسانی نسل سے بہتر ہوتے ہیں، اور کچھ جانوروں کی نسلوں میں خاص فطری صلاحیتیں ہوتی ہیں۔ جانوروں کی نسل کو بھیڑیے کی نسل، شیر کی نسل، ریچھ کی نسل، لومڑی کی نسل جیسی درجنوں شاخوں میں تقسیم کیا گیا ہے۔</li><li><strong>ترچھی نسل</strong>: ترچھوں سے ڈھکے ہوئے جسم والی نسلیں، جو زیادہ تر آبی یا مرطوب ماحول میں رہتی ہیں، اور کچھ ترچھی نسلوں میں پانی کے نیچے سانس لینے اور پانی کو کنٹرول کرنے کی صلاحیت ہوتی ہے۔ ڈریگن نسل ترچھی نسل کی سب سے طاقتور شاخ ہے۔</li><li><strong>پروں والی نسل</strong>: پروں والی نسلیں، جو اپنی اڑان کی صلاحیت کے لیے مشہور ہیں، زیادہ تر اونچائی یا پہاڑی ماحول میں رہتی ہیں۔ پروں والی نسل کو عقاب کی نسل، کرینک کی نسل، تتلی کی نسل جیسی شاخوں میں تقسیم کیا گیا ہے۔</li><li><strong>درختوں کی نسل</strong>: پودوں کی شکل کو بنیادی خصوصیت کے طور پر لیتی ہوئی نسلیں، جن کی زندگی لمبی ہے اور قدرتی ماحول کے ساتھ اعلیٰ سمبیوسس ہے، اور کچھ درختوں کی نسلوں میں پودوں کو کنٹرول کرنے اور شفا دینے کی صلاحیت ہوتی ہے۔</li></ul><h3 id="ب-توانائی-گاڑھی-نسل" tabindex="-1">(ب) توانائی گاڑھی نسل <a class="header-anchor" href="#ب-توانائی-گاڑھی-نسل" aria-label="Permalink to &quot;(ب) توانائی گاڑھی نسل&quot;">​</a></h3><ul><li><strong>روحانی نسل</strong>: آسمان اور زمین کی روحانی توانائی سے گاڑھی ہوئی زندگی، جس کی شکل شعور کے ساتھ بدل سکتی ہے اور توانائی کو کنٹرول کرنے کی صلاحیت انتہائی مضبوط ہے۔ روحانی نسل سدھن میں سب سے زیادہ فطری صلاحیت والی نسلوں میں سے ایک ہے۔</li><li><strong>آگ کی نسل</strong>: آگ کی توانائی سے گاڑھی ہوئی زندگی، جس کے جسم کا درجہ حرارت انتہائی اونچا ہے، آگ کے منتروں میں مہارت رکھتی ہے، زیادہ تر آتش فشاں یا اعلی درجہ حرارت والے علاقوں میں رہتی ہے۔</li><li><strong>پانی کی نسل</strong>: پانی کے جوہر سے گاڑھی ہوئی زندگی، جس کا جسم نیم شفاف مائع کی شکل کا ہے، پانی کے منتروں اور شفا میں مہارت رکھتی ہے، زیادہ تر آبی ماحول میں رہتی ہے۔</li><li><strong>ہوا کی نسل</strong>: ہوا کے جوہر سے گاڑھی ہوئی زندگی، جس کا جسم ہوا کی طرح ہلکا ہے، ہوا کے منتروں اور رفتار کی لڑائی میں مہارت رکھتی ہے۔</li><li><strong>بجلی کی نسل</strong>: بجلی کی توانائی سے گاڑھی ہوئی زندگی، جس کے جسم میں مضبوط برقی رو ہے، بجلی کے منتروں میں مہارت رکھتی ہے، حملہ آور قوت انتہائی مضبوط ہے۔</li></ul><h3 id="ج-مکینیکل-تعمیراتی-نسل" tabindex="-1">(ج) مکینیکل تعمیراتی نسل <a class="header-anchor" href="#ج-مکینیکل-تعمیراتی-نسل" aria-label="Permalink to &quot;(ج) مکینیکل تعمیراتی نسل&quot;">​</a></h3><ul><li><strong>مشینوں کی نسل</strong>: عین مطابق مکینیکل تعمیر کے جسم والی نسل، جس کا شعور کا مرکز جسم کے بیچ میں واقع ہے، جس میں مضبوط کمپیوٹیشن کی صلاحیت اور جسمانی دفاع کی صلاحیت ہے۔</li><li><strong>عددی نسل</strong>: وہ نسل جو اعداد و کوڈ کو زندگی کی بنیاد کے طور پر لیتی ہے، معلومات کی جگہ میں موجود ہے، ڈیجیٹل دنیا میں آزادانہ سفر کر سکتی ہے اور ڈیٹا کو کنٹرول کر سکتی ہے۔</li><li><strong>کرسٹل کی نسل</strong>: کرسٹل تعمیر کے جسم والی نسل، کرسٹل توانائی کو ذخیرہ اور تبدیل کر سکتے ہیں، اور کچھ کرسٹل کی نسلوں میں توانائی کو بڑھانے اور ریفریکشن کرنے کی صلاحیت ہے۔</li></ul><h3 id="د-شعوری-معلوماتی-نسل" tabindex="-1">(د) شعوری معلوماتی نسل <a class="header-anchor" href="#د-شعوری-معلوماتی-نسل" aria-label="Permalink to &quot;(د) شعوری معلوماتی نسل&quot;">​</a></h3><ul><li><strong>خوابوں کی نسل</strong>: خوابوں اور شعور کی جگہ میں موجود زندگی، جو دوسروں کے خوابوں میں داخل ہو سکتی ہے، اور شعوری مواصلت کو بنیادی طریقے کے طور پر لیتی ہے۔</li><li><strong>سائے کی نسل</strong>: سائے کی شکل میں موجود زندگی، جو چیزوں یا جانداروں سے منسلک ہو سکتی ہے، جس میں چھپنے اور چپکے سے چلنے کی صلاحیت ہے۔</li><li><strong>سوچ کی نسل</strong>: وہ زندگی جو خالص سوچ کو وجود کی شکل کے طور پر لیتی ہے، جو سوچ کے ذریعے براہ راست مادّی دنیا کو متاثر کر سکتی ہے، ذہنی طاقت انتہائی مضبوط ہے۔</li></ul><h3 id="ہ-مخلوط-تبدیلی-نسل" tabindex="-1">(ہ) مخلوط تبدیلی نسل <a class="header-anchor" href="#ہ-مخلوط-تبدیلی-نسل" aria-label="Permalink to &quot;(ہ) مخلوط تبدیلی نسل&quot;">​</a></h3><ul><li><strong>نیم جانور نسل</strong>: انسانی نسل اور جانوروں کی نسل کی مخلوط شکل، جس میں انسانی نسل کی عقل اور جانوروں کی نسل کی جسمانی صلاحیت دونوں موجود ہیں۔</li><li><strong>دیوتا روح نسل</strong>: مادّی نسل اور توانائی نسل کی مخلوط شکل، جس میں ایک ہی وقت میں مادّی جسم اور توانائی کو کنٹرول کرنے کی صلاحیت ہے۔</li><li><strong>انسان-مشین نسل</strong>: انسانی نسل اور مشین نسل کی مخلوط شکل، جس کے جسم کا کچھ حصہ مکینیکل ہے، جس میں حیاتیاتی اور میکانکی دونوں فوائد ہیں۔</li><li><strong>دوہری روح جسم</strong>: ایک خاص زندگی کی شکل جس میں ایک جسم میں دو آزادانہ روحیں موجود ہیں، جس کے اخلاقی مسائل 《58-دوہری روح اخلاقی معیارات》 میں تفصیل سے بیان کیے گئے ہیں۔</li></ul><h2 id="iv-تمام-نسلوں-کا-سمبیوسس-تعلق" tabindex="-1">IV. تمام نسلوں کا سمبیوسس تعلق <a class="header-anchor" href="#iv-تمام-نسلوں-کا-سمبیوسس-تعلق" aria-label="Permalink to &quot;IV. تمام نسلوں کا سمبیوسس تعلق&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب میں تمام نسلوں کا تعلق &quot;سمبیوسس&quot; کو مرکز کے طور پر لیتی ہے، جو خاص طور پر اس طرح ظاہر ہوتا ہے:</p><ol><li><strong>معاشی سمبیوسس</strong>: ہر نسل اپنے اپنے فوائد کا مظاہرہ کرتی ہے، مشترکہ پیداوار کے معاہدے کے نظام میں مختلف کردار ادا کرتی ہے، اور تکمیلی معاشی تعاون کا نیٹ ورک بناتی ہے۔</li><li><strong>ثقافتی سمبیوسس</strong>: ہر نسل کے ثقافتی روایات کا احترام اور تحفظ کیا جاتا ہے، اور ثقافتی تبادلے اور باہمی سیکھنا تہذیب کی مجموعی خوشحالی کو فروغ دیتا ہے۔</li><li><strong>سدھن کا سمبیوسس</strong>: ہر نسل کے سدھن کے نظام باہمی طور پر کھلے ہیں اور ایک دوسرے سے سیکھتے ہیں، اور تین سو اصل سدھن کے نظام تمام نسلوں کے لیے برابر ارتقاء کے راستے فراہم کرتے ہیں۔</li><li><strong>سیاسی سمبیوسس</strong>: تمام نسلوں کے نمائندہ متناسب طور پر اینکر کونسل میں حصہ لیتے ہیں، تہذیب کے اہم معاملات پر مشترکہ فیصلہ کرتے ہیں، اور ہر نسل کے بولنے کے حق کو یقینی بناتے ہیں۔</li><li><strong>ماحولیاتی سمبیوسس</strong>: ہر نسل قدرتی ماحول کے ساتھ سمبیوسس تعلق بناتی ہے، اور مختلف نسلوں کی جسمانی خصوصیات ماحولیاتی نظام کے تنوع اور توازن کو برقرار رکھنے میں مدد کرتی ہیں۔</li></ol><h2 id="v-نسلی-تنازعات-کی-روک-تھام-اور-حل" tabindex="-1">V. نسلی تنازعات کی روک تھام اور حل <a class="header-anchor" href="#v-نسلی-تنازعات-کی-روک-تھام-اور-حل" aria-label="Permalink to &quot;V. نسلی تنازعات کی روک تھام اور حل&quot;">​</a></h2><p>اگرچہ اینکر سمبیوسس تہذیب نے تمام نسلوں کی برابری کا اصول قائم کیا ہے، پھر بھی نسلی اختلافات اور تاریخی تضادات اب بھی تنازعات پیدا کر سکتے ہیں۔ ریاست نسلی تنازعات کی روک تھام اور حل کے لیے درج ذیل میکانزم قائم کرتی ہے:</p><ul><li><strong>نسلی امور کا شعبہ</strong>: خاص طور پر تمام نسلوں کے درمیان تعلقات کو مربوط کرنے، نسلی تنازعات کو حل کرنے اور نسلی تبادلے کو فروغ دینے کے لیے ذمہ دار۔</li><li><strong>نسلی مفاہمت کمیٹی</strong>: تمام نسلوں کے نمائندوں پر مشتمل، نسلی تنازعات میں ثالثی اور تاریخی مفاہمت کو فروغ دینے کے لیے ذمہ دار۔</li><li><strong>امتیاز مخالف قانون</strong>: نسل کی بنیاد پر امتیازی سلوک پر پابندی، اور نسلی امتیازی سلوک پر قانون کے مطابق سزا۔</li><li><strong>ثقافتی تبادلے کا پروگرام</strong>: باقاعدگی سے تمام نسلوں کے درمیان ثقافتی تبادلے کے پروگرام منعقد کرنا، باہمی افہام و تفہیم اور احترام کو بڑھانا۔</li><li><strong>مخلوط رہائشی علاقے</strong>: تمام نسلوں کی مخلوط رہائش کی حوصلہ افزائی کرنا، نسلی علیحدگی کو توڑنا، اور روزمرہ کے تبادلے کو فروغ دینا۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>تمام نسلیں ہنگ یوآن ژو کی سب سے قیمتی دولت ہیں۔ زندگی کی شکلوں کا تنوع تقسیم کی جڑ نہیں ہے، بلکہ سمبیوسس ارتقاء کا محرک ہے۔ اینکر سمبیوسس تہذیب تمام نسلوں کی برابری کے اصول کو قائم کرکے، پانچ نسبتی خطوں کی درجہ بندی کو بنا کر، تمام نسلوں کے سمبیوسس تعاون کو فروغ دے کر، اور نسلی تنازعات کی روک تھام اور حل کرکے، تمام نسلوں کو لوٹ مار اور جنگ کی تاریخ سے آزاد کرتی ہے، اور مشترکہ طور پر سمبیوسس ارتقاء کے نئے دور کی طرف بڑھتی ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>51-人族定位与特质 (انسانی نسل کی پوزیشن اور خصوصیات)</li><li>52-异族分类与共生 (غیر ملکی نسلوں کی درجہ بندی اور سمبیوسس)</li><li>05-万族共进基本纲领 (تمام نسلوں کی مشترکہ ترقی کا بنیادی پروگرام)</li><li>40-共生宪法总纲 (سمبیوسس آئین کے عمومی اصول)</li></ul>',30)])])}const b=r(o,[["render",n]]);export{c as __pageData,b as default};
